 private final Runnable clock=new Runnable(){public void run(){if(dialog==null||connectedAt==0)return;long s=(System.currentTimeMillis()-connectedAt)/1000;if(!reconnecting)status.setText(String.format(java.util.Locale.ROOT,"%02d:%02d",s/60,s%60));handler.postDelayed(this,1000);}};
 private void showStatus(String value){if(status==null)return;if(reconnecting){status.setText(I18n.t("Đang nối lại…"));return;}if(I18n.t("Đã kết nối").equals(value)){if(connectedAt==0){connectedAt=System.currentTimeMillis();handler.post(clock);}return;}if(connectedAt==0)status.setText(value);}
 private void permissions(Runnable task){boolean camera=mode.equals("audio")||activity.checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED;boolean mic=activity.checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;if(camera&&mic){task.run();return;}permission=task;activity.requestPermissions(mode.equals("audio")?new String[]{Manifest.permission.RECORD_AUDIO}:new String[]{Manifest.permission.RECORD_AUDIO,Manifest.permission.CAMERA},901);}
 void permissionsResult(int[] grants){Runnable task=permission;permission=null;for(int grant:grants)if(grant!=PackageManager.PERMISSION_GRANTED){toast(I18n.t("Cần cấp quyền để bắt đầu cuộc gọi."));end(true);return;}if(grants.length>0&&task!=null&&dialog!=null)task.run();else end(true);}
 private void media(Runnable done){if(rtc!=null){done.run();return;}final Dialog generation=dialog;NativeApi.shared.call("GET","/api/call-config",null,(config,error,code)->{if(dialog!=generation||closed||dialog==null)return;if(error!=null){toast(error);end(true);return;}try{rtc=new NativeRtc(activity,config,local,remote,new NativeRtc.Events(){public void connection(String state){if(ending||dialog!=generation)return;if(state.equals("CONNECTED")||state.equals("COMPLETED")){restored();}else if(state.equals("DISCONNECTED")||state.equals("FAILED")){reconnect();if(!incoming&&ready&&rtc!=null)rtc.restart("call");}}public void status(String value){if(!ending&&dialog==generation)showStatus(value);}public void signal(String peer,JSONObject payload){if(ending||dialog!=generation)return;try{payload.put("type","call-signal");payload.put("callId",id);KinnectService.send(payload);}catch(JSONException ignored){}}});rtc.media(activity,!mode.equals("audio"));audio=(android.media.AudioManager)activity.getSystemService(Activity.AUDIO_SERVICE);previousMode=audio.getMode();previousSpeaker=audio.isSpeakerphoneOn();audio.setMode(android.media.AudioManager.MODE_IN_COMMUNICATION);audio.setSpeakerphoneOn(!mode.equals("audio"));done.run();}catch(Exception e){toast(I18n.t("Không mở được camera/micro."));end(true);}});}
 public void event(JSONObject m){String type=m.optString("type");if(type.equals("call-incoming")&&NativeCallEnds.contains(m.optString("callId")))return;if(type.equals("welcome")){ready=true;if(reconnecting&&accepted&&id!=null)KinnectService.send(NativeSocket.json("type","call-resume","callId",id));return;}if(type.equals("call-incoming")){if(dialog!=null){KinnectService.send(NativeSocket.json("type","call-decline","callId",m.optString("callId")));return;}id=m.optString("callId");mode=m.optString("mode","video");incoming=true;accepted=false;open(m.optJSONObject("from"));return;}if(type.equals("call-ringing")){if(dialog!=null&&m.optString("requestId").equals(requestId)){id=m.optString("callId");status.setText(I18n.t("Đang đổ chuông…"));}else KinnectService.send(NativeSocket.json("type","call-end","callId",m.optString("callId")));return;}if(type.equals("call-ended")&&dialog!=null&&((id!=null&&id.equals(m.optString("callId")))||(requestId!=null&&requestId.equals(m.optString("requestId"))))){String reason=m.optString("reason");toast(reason.equals("busy")?I18n.t("Người này đang bận."):reason.equals("unavailable")?I18n.t("Người này chưa sẵn sàng nhận cuộc gọi."):I18n.t("Cuộc gọi đã kết thúc."));end(false);return;}if(dialog==null||id==null||!id.equals(m.optString("callId")))return;if(type.equals("call-reconnecting")){reconnect();return;}if(type.equals("call-resumed")){if(!incoming&&rtc!=null)rtc.restart("call");return;}if(type.equals("call-accepted")&&rtc!=null){accepted=true;stopDial();cue(android.media.ToneGenerator.TONE_PROP_ACK);status.setText(I18n.t("Đang kết nối…"));if(!incoming)rtc.offer("call");handler.postDelayed(()->{if(dialog!=null&&rtc!=null&&status.getText().toString().equals("Đang kết nối…")){toast(I18n.t("Chưa kết nối được media. Vui lòng thử mạng khác."));end(true);}},35000);}if(type.equals("call-signal")&&rtc!=null)rtc.signal("call",m);}
 public void closed(){ready=false;if(dialog!=null){if(accepted)reconnect();else{toast(I18n.t("Mất kết nối cuộc gọi."));end(false);}}}
 private void end(boolean notify){if(ending)return;ending=true;boolean hadCall=dialog!=null;String endedId=id,endedRequest=requestId;boolean decline=incoming&&!accepted;reconnecting=false;handler.removeCallbacksAndMessages(null);if(pip)restorePip();stopDial();stopRing();if(returnBanner!=null&&returnBanner.getParent()!=null)((ViewGroup)returnBanner.getParent()).removeView(returnBanner);returnBanner=null;permission=null;Dialog old=dialog;dialog=null;id=null;requestId=null;accepted=false;connectedAt=0;controls=null;incomingBar=null;
 if(endedId!=null&&KinnectService.pendingIncoming!=null&&endedId.equals(KinnectService.pendingIncoming.optString("callId")))KinnectService.clearCall();if(notify){if(endedId!=null)KinnectService.send(NativeSocket.json("type",decline?"call-decline":"call-end","callId",endedId));else if(endedRequest!=null)KinnectService.send(NativeSocket.json("type","call-cancel","requestId",endedRequest));}if(old!=null)old.dismiss();if(rtc!=null){NativeRtc previous=rtc;rtc=null;previous.close();}if(audio!=null){audio.setMode(previousMode);audio.setSpeakerphoneOn(previousSpeaker);audio=null;}if(hadCall)cue(android.media.ToneGenerator.TONE_PROP_NACK); }

 void close(){closed=true;JSONObject ringing=dialog!=null&&incoming&&!accepted?KinnectService.pendingIncoming:null;end(ringing==null);if(ringing!=null){KinnectService.pendingIncoming=ringing;KinnectService.ringAgain();}KinnectService.unlisten(this);}
